def block(start):
    """the exact text of one method block that starts with `start` (up to its closing }\"\"\") or }\"\"\"))"""
    a = P.s.index(start)
    assert P.s.count(start) == 1, start[:120]
    b = P.s.index('}"""', a) + len('}"""')
    if P.s[b:b + 2] == "))":
        b += 2
    elif P.s[b:b + 1] == ")":
        b += 1
    return P.s[a:b]


def jm(cls, body):
    return 'M(%s, r"""\n%s\n}""")' % (cls, body.strip("\n").rstrip().rstrip("}").rstrip())


