# what row r of a class branch still needs: { branch points needed, branch points spent, row-above points needed, row-above spent, the
# class level needed (0 = no floor), the class level }
M(v3c, r"""
public static int[] needOfC(@PKG@.TreeData d, int r, int lvl) {
  int[] o = new int[6];
  if (d == null || r < 0 || r >= NR) return o;
  int n = RNUM[r];
  int step = @PKG@.TreeCfg.CL_STEP;
  o[0] = step * (n - 1);
  o[1] = spentBranch(d, RB[r]);
  if (n > 1 && r - 1 >= BR0[RB[r]]) {
    int a = @PKG@.TreeCfg.CL_ABOVE;
    int cap = rowCapR(r - 1);
    o[2] = a > cap ? cap : a;
    o[3] = rowSpentR(d, r - 1);
  }
  o[4] = (@PKG@.TreeCfg.CL_FLOOR && n > 1) ? 5 * (n - 1) : 0;
  o[5] = lvl;
  return o;
}""")
M(v3c, r"""
public static boolean rowOpenC(@PKG@.TreeData d, int r, int lvl) {
  if (r < 0 || r >= NR) return false;
  if (RNUM[r] <= 1) return true;
  int[] o = needOfC(d, r, lvl);
  if (o[1] < o[0]) return false;
  if (o[2] > 0 && o[3] < o[2]) return false;
  if (o[4] > 0 && lvl >= 0 && lvl < o[4]) return false;
  return true;
}""")
